arguments.command:
cd /tmp/work && cat > /tmp/work/h5.py <<'EOF'
import sys, json, h5py, zipfile
for p in sys.argv[1:]:
    print("=" * 20, p)
    if p.endswith('.keras'):
        zf = zipfile.ZipFile(p)
        for i in zf.infolist(): print(' ', i.filename, i.file_size)
        cfg = json.loads(zf.read('config.json'))
        print(json.dumps(cfg, indent=1)[:6000])
        print("metadata:", zf.read('metadata.json')[:500])
    else:
        fh = h5py.File(p, 'r')
        print(" attrs:", {k: (str(v)[:80]) for k, v in fh.attrs.items()})
        def walk(name, obj):
            print("  ", name, dict(obj.attrs) if len(obj.attrs) < 6 else list(obj.attrs.keys()))
        fh.visititems(walk)
        raw = fh.attrs.get('model_config')
        if raw is not None:
            if isinstance(raw, bytes): raw = raw.decode()
            print(json.dumps(json.loads(raw), indent=1)[:6000])
EOF
python3 -I h5.py /app/samples/sample_14.h5 /app/samples/sample_15.keras 2>&1 | head -300

