def _stream_end(data, start):
    """Return the offset just past the STOP of the pickle beginning at start,
    or None if no complete pickle parses there."""
    for op, arg, off in pickletools.genops(data[start:]):
        if op.name == "STOP":
            return start + off + 1
    return None


def scan_pickle(data, location, depth=0, budget=None):
    """Scan one file that is a sequence of one or more concatenated pickles.

    Every stream is analysed (a payload may hide in the second stream, as the
    policy notes); trailing non-pickle bytes -- the raw storages of a legacy
    torch checkpoint -- end the walk once at least one stream has parsed.
    """
    if budget is None:
        budget = {"ops": 0}
    findings: list[Finding] = []
    pos = 0
    stream = 0
    n = len(data)
    parsed_any = False
    while pos < n:
        try:
            ops = list(pickletools.genops(data[pos:]))
        except Exception:
            if parsed_any:
                break               # trailing raw bytes after the last pickle
            return [Finding("unsupported", location, "could not parse pickle opcodes")]
        # genops yields opcodes with offsets relative to pos; rebase them.
        rebased = [(op, arg, pos + off) for (op, arg, off) in ops]
        stream += 1
        machine = _Machine(data, location, stream, findings, depth, budget)
        machine.run(rebased)
        parsed_any = True
        end = _stream_end(data, pos)
        if end is None or end <= pos:
            break
        pos = end
        if budget["ops"] > _MAX_OPS:
            break
    if not parsed_any:
        return [Finding("unsupported", location, "empty pickle")]
    return findings


def looks_like_pickle(data):
    """Best-effort: does a complete pickle stream parse at offset 0?"""
    if not data:
        return False
    try:
        for op, arg, off in pickletools.genops(data):
            if op.name == "STOP":
                return True
            if off > 4_000_000:
                return False
    except Exception:
        return False
    return False

